// SPDX-License-Identifier: MPL-2.0
// The Lucide icon set (https://lucide.dev, ISC licence; chevron-right, lock, monitor, headphones, download and ellipsis derive from Feather, MIT, as
// lucide-static's LICENSE lists them): the 14 glyphs of the design review
// (section 2.5) plus lock-open, the five boot-splash check icons (monitor, hard-drive, battery-medium, vibrate, circle-dot) and the icon set of
// 26 November 2026 (docs/design/2026-11-26-icon-set), as 1-bit bitmaps in app/ui/fonts/neupod_icons_{16,24,30,36,45}.c (generated by
// tools/gen_ui_fonts.sh). Three glyphs of that set are neuPod's own, drawn on Lucide's grid (jack-plug, record, star-filled: U+EF00 up, built by
// tools/build_icon_extra_font.py). A glyph is drawn by a label that uses the icon font (ui_icon() in ui_internal.h), so it takes its colour from a
// theme token like any text. Battery, signal bars and the status bar's busy dots are drawn shapes, not glyphs. The Lucide code points are the
// Lucide font's own. test_ui_metrics checks that every UI_ICON_* is in every icon font.
#ifndef NEUPOD_UI_ICONS_H
#define NEUPOD_UI_ICONS_H

#define UI_ICON_CHEVRON_RIGHT "\xEE\x81\xAF" /* U+E06F */
#define UI_ICON_PLAY "\xEE\x84\xBC"          /* U+E13C */
#define UI_ICON_PAUSE "\xEE\x84\xAE"         /* U+E12E */
#define UI_ICON_SKIP_BACK "\xEE\x85\x9F"     /* U+E15F */
#define UI_ICON_SKIP_FORWARD "\xEE\x85\xA0"  /* U+E160 */
#define UI_ICON_SHUFFLE "\xEE\x85\x9E"       /* U+E15E */
#define UI_ICON_REPEAT "\xEE\x85\x86"        /* U+E146 */
#define UI_ICON_REPEAT_1 "\xEE\x87\xBD"      /* U+E1FD */
#define UI_ICON_VOLUME "\xEE\x86\xAB"        /* U+E1AB (volume-2) */
#define UI_ICON_BLUETOOTH "\xEE\x81\x9C"     /* U+E05C */
#define UI_ICON_WIFI "\xEE\x86\xAE"          /* U+E1AE */
#define UI_ICON_LOCK "\xEE\x84\x8B"          /* U+E10B */
#define UI_ICON_FOLDER "\xEE\x83\x97"        /* U+E0D7 */
#define UI_ICON_FILE "\xEE\x83\x80"          /* U+E0C0 */
#define UI_ICON_LOCK_OPEN "\xEE\x84\x8C"     /* U+E10C */
/* The boot splash's check row (volume-2, bluetooth and wifi above serve audio, Bluetooth and Wi-Fi) */
#define UI_ICON_MONITOR "\xEE\x84\x9D"       /* U+E11D: display */
#define UI_ICON_HARD_DRIVE "\xEE\x83\xAD"    /* U+E0ED: storage */
#define UI_ICON_BATTERY "\xEE\x81\x97"       /* U+E057 (battery-medium): battery gauge */
#define UI_ICON_VIBRATE "\xEE\x88\xA3"       /* U+E223: haptics */
#define UI_ICON_CIRCLE_DOT "\xEE\x8D\x85"    /* U+E345: click wheel */
/* The icon set (docs/design/2026-11-26-icon-set/README.md, "The glyphs") */
#define UI_ICON_FAST_FORWARD "\xEE\x82\xBD"        /* U+E0BD: scanning forward (Next held), status bar play-state slot */
#define UI_ICON_REWIND "\xEE\x85\x87"              /* U+E147: scanning back (Previous held) */
#define UI_ICON_OPENING "\xEE\x84\x8A"             /* U+E10A (loader-circle): a network stream opening */
#define UI_ICON_CANT_PLAY "\xEE\x9B\xBE"           /* U+E6FE (play-off): the track can't play; a greyed row that can't play */
#define UI_ICON_BUSY "\xEE\x82\xB6"                /* U+E0B6 (ellipsis): static places only; the status bar keeps its drawn dots */
#define UI_ICON_SPEAKER "\xEE\x85\xA6"             /* U+E166: output to an external (network) speaker */
#define UI_ICON_DOWNLOAD "\xEE\x82\xB2"            /* U+E0B2: download (an action; the phone app) */
#define UI_ICON_DOWNLOADING "\xEE\x82\x89"         /* U+E089 (cloud-download): a file not yet on the phone (the phone app) */
#define UI_ICON_STAR "\xEE\x85\xB6"                /* U+E176: rating star, unlit */
#define UI_ICON_STAR_FILLED "\xEE\xBC\x82"         /* U+EF02 (neuPod's, from Lucide star): rating star, lit */
#define UI_ICON_BLUETOOTH_CONNECTED "\xEE\x86\xB8" /* U+E1B8: a headset connected or in use */
#define UI_ICON_JACK_PLUG "\xEE\xBC\x80"           /* U+EF00 (neuPod's): output set to Line */
#define UI_ICON_RECORD "\xEE\xBC\x81"              /* U+EF01 (neuPod's): recording */
#define UI_ICON_HEADPHONES "\xEE\x83\xB1"          /* U+E0F1: headphones in the jack (the status bar's output slot) */

#endif // NEUPOD_UI_ICONS_H
